=fConfigGeral()

Create Cursor csDestinos (Processos c(20), Codigos n(6), Drives c(10), Emps c(3), Dopes  c(20), EmpDs c(3), ;
						  DopeDs c(20), TpProdutos n(2), Dias n(3), GruconOs n(1), GruconDs n(1), EmpDests n(1), ;
						  Agrupar n(1), NovoCods n(1), CorTams n(1), MoeVals n(1), Situas n(1), Franquias n(1), PctMins n(12,2), ;
						  PctMaxs n(12,2), Custos n(1), Impostos n(1), Imagem n(1), MantProds n(1), Barras n(1), ;
						  Mccrs n(1), Cheques n(1), Delets n(1), DesItens n(1), Mont... [TRUNCADO]

Insert Into csDestinos (Processos, Emps, Dopes, Codigos, Drives, EmpDs, DopeDs, TpProdutos, Dias, GruConOs, ;
						GruConDs, EmpDests, Agrupar, NovoCods, CorTams, MoeVals, Situas, Franquias, PctMins, PctMaxs, ;
						Custos, Impostos, Imagem, MantProds, Barras, Mccrs, Cheques, Delets, DesItens, MontaObs, ;
						ChkCons, MantemMats, MantDPros, GdeGrupos, CUnis, OriCompos, Origems, Destinos, SemItens, ;
						Fiscais, Recalculos, PctCopias, OpItens, MovMZeros, MovCParc, cIdChaves, pctcomps, Glob... [TRUNCADO]

ThisForm.Pagina.Dados.lblNotas.Caption = 'Tipo de Produto no Destino ' + ;
										 '(1-Cód.; 2-Descr.; ' + ;
										 '3-Estoq.; 4-C/Casamento; ' + ;
										 '5-Barra; 6-Cód. Exato; ' + ;
										 '7-Cód. Exato/Nova Descr.; ' + ;
										 '8-Descr. + Peso; ' + ;
										 '9-Cód. + Grupo + Subgrupo + Valor; ' + ;
										 '10-Identidade; 11-Ident./Produto; ' + ;
										 '12-Ident.Compos).'
* Fim *********************************************************************************

* Coluna Produto
Return InList(ThisForm.pcEscolha, 'INSERIR', 'ALTERAR') And ;
   Not Empty(ThisForm.Pagina.Dados.grdDestinos.Column2.Text1.Value) And ;
   Not Empty(ThisForm.Pagina.Dados.grdDestinos.Column3.Text1.Value)
* Fim *********************************************************************************

* Coluna Dias
Return InList(ThisForm.pcEscolha, 'INSERIR', 'ALTERAR') And ;
   Not Empty(ThisForm.Pagina.Dados.grdDestinos.Column2.Text1.Value) And ;
   Not Empty(ThisForm.Pagina.Dados.grdDestinos.Column3.Text1.Value) And ;
   Not Empty(ThisForm.Pagina.Dados.grdDestinos.Column4.Text1.Value)
* Fim *********************************************************************************

* Coluna Margem Mínima
Return InList(ThisForm.pcEscolha, 'INSERIR', 'ALTERAR') And ;
   Not Empty(ThisForm.Pagina.Dados.grdDestinos.Column2.Text1.Value) And ;
   Not Empty(ThisForm.Pagina.Dados.grdDestinos.Column3.Text1.Value) And ;
   Not Empty(ThisForm.Pagina.Dados.grdDestinos.Column4.Text1.Value)
* Fim *********************************************************************************

* Coluna Margem Máxima
Return InList(ThisForm.pcEscolha, 'INSERIR', 'ALTERAR') And ;
   Not Empty(ThisForm.Pagina.Dados.grdDestinos.Column2.Text1.Value) And ;
   Not Empty(ThisForm.Pagina.Dados.grdDestinos.Column3.Text1.Value) And ;
   Not Empty(ThisForm.Pagina.Dados.grdDestinos.Column4.Text1.Value)
* Fim *********************************************************************************

* Coluna Grande Grupo
Return InList(ThisForm.pcEscolha, 'INSERIR', 'ALTERAR') And ;
   Not Empty(ThisForm.Pagina.Dados.grdDestinos.Column2.Text1.Value) And ;
   Not Empty(ThisForm.Pagina.Dados.grdDestinos.Column3.Text1.Value)
* Fim *********************************************************************************

* Coluna Unidade
Return InList(ThisForm.pcEscolha, 'INSERIR', 'ALTERAR') And ;
	   Not Empty(ThisForm.Pagina.Dados.grdDestinos.Column2.Text1.Value) And ;
	   Not Empty(ThisForm.Pagina.Dados.grdDestinos.Column3.Text1.Value)
* Fim *********************************************************************************

* Coluna Unidade
Return InList(ThisForm.pcEscolha, 'INSERIR', 'ALTERAR') And ;
	   Not Empty(ThisForm.Pagina.Dados.grdDestinos.Column2.Text1.Value) And ;
	   Not Empty(ThisForm.Pagina.Dados.grdDestinos.Column3.Text1.Value)
* Fim *********************************************************************************

* Coluna Unidade
Return InList(ThisForm.pcEscolha, 'INSERIR', 'ALTERAR') And ;
	   Not Empty(ThisForm.Pagina.Dados.grdDestinos.Column2.Text1.Value) And ;
	   Not Empty(ThisForm.Pagina.Dados.grdDestinos.Column3.Text1.Value)
* Fim *********************************************************************************

ThisForm.Pagina.Dados.lblNotas.Caption = 'Operação a ser Transferida :' + CHR(13) + CHR(10) + ;
										 'E - Somente Entradas' + CHR(13) + CHR(10) + ;
										 'S - Somente Saídas' + CHR(13) + CHR(10) + ;
										 'Em Branco - Ambas'

If InList(ThisForm.pcEscolha, 'INSERIR', 'ALTERAR')
	If Not InList(This.Value, 'E', 'S', ' ')
		=Messagebox('Operação de Item Inválida!!! Utilize: ' + Chr(13) + ;
					'E - Somente Entradas; ' + Chr(13) + ;
					'S - Somente Saídas; ' + Chr(13) + ;
					'Em branco - Ambas.', 0+48, '')
		Return 0
	EndIf
EndIf
